<?php defined('BASEPATH') or exit('No direct script access allowed'); ?>
<div class="card">
    <div class="card-header d-flex justify-content-between align-items-center"><div><h4 class="header-title mb-0">Wali Siswa</h4><small class="text-muted">Satu wali dapat direlasikan ke beberapa anak.</small></div><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-danger" id="openTrash"><i class="ri-delete-bin-6-line me-1"></i>Trash</button><button class="btn btn-sm btn-primary" id="add" title="Tambah wali" aria-label="Tambah wali"><i class="ri-user-add-line"></i></button></div></div>
    <div class="card-body">
        <div class="alert alert-light border mb-3"><strong>Status wali:</strong> Aktif berarti akun wali dapat digunakan untuk login dan relasinya dihitung sebagai wali aktif. Nonaktif memblokir akun serta menyembunyikannya dari relasi aktif tanpa menghapus data.</div>
        <div class="row g-2 mb-3"><div class="col-md-5"><input id="search" class="form-control" placeholder="Cari nama, telepon, atau email"></div><div class="col-md-3"><select id="waliStatusFilter" class="form-select"><option value="">Semua status</option><option>AKTIF</option><option>NONAKTIF</option></select></div><div class="col-md-2"><button id="filter" class="btn btn-outline-primary w-100" title="Terapkan filter" aria-label="Terapkan filter" data-bs-toggle="tooltip"><i class="ri-filter-3-line"></i></button></div></div>
        <div id="rows" class="sdk-record-list"><div class="sdk-record-empty">Memuat data...</div></div>
        <div class="sdk-pager-wrap"><div><small id="info" class="text-muted"></small><div class="mt-2" id="waliPagination"></div></div><div class="sdk-page-size"><label for="waliPageSize" class="mb-0">Tampilkan</label><select class="form-select form-select-sm" id="waliPageSize"><option value="10" selected>10</option><option value="25">25</option><option value="50">50</option><option value="100">100</option></select><span>entri</span></div></div>
    </div>
</div>

<div class="modal fade" id="formModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content">
    <div class="modal-header"><h5 class="modal-title">Data Wali</h5><button class="btn-close" data-bs-dismiss="modal"></button></div>
    <div class="modal-body"><form id="form"><input type="hidden" name="id"><input type="hidden" name="web_csrf_token" value="<?= html_escape($csrf_token) ?>">
        <div class="mb-3"><label class="form-label" for="waliName">Nama *</label><input id="waliName" name="nama_wali" class="form-control" required></div>
        <div class="mb-3"><label class="form-label" for="waliRelationship">Hubungan</label><input id="waliRelationship" name="hubungan" class="form-control" list="waliRelationshipOptions" placeholder="Contoh: Ayah atau Ibu"><datalist id="waliRelationshipOptions"><option value="Ayah"><option value="Ibu"><option value="Wali"><option value="Kakek"><option value="Nenek"></datalist><small class="text-muted d-block mt-2">Jenis hubungan akan ditampilkan bersama nama wali pada detail siswa.</small></div>
        <div class="mb-3"><label class="form-label" for="waliPhone">Telepon</label><input id="waliPhone" name="no_telp" class="form-control"></div>
        <div class="mb-3"><label class="form-label" for="waliEmail">Email</label><input id="waliEmail" name="email" type="email" class="form-control"></div>
        <div class="mb-3"><label class="form-label" for="waliUsername">Username *</label><input id="waliUsername" name="username" class="form-control" minlength="4" maxlength="100" pattern="[A-Za-z0-9._-]+" autocomplete="off" required><small class="text-muted d-block mt-2">Gunakan huruf, angka, titik, garis bawah, atau tanda hubung.</small></div>
        <div><label class="form-label" for="waliAddress">Alamat</label><textarea id="waliAddress" name="alamat" class="form-control"></textarea></div>
    </form></div>
    <div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Tutup</button><button class="btn btn-primary" id="save">Simpan</button></div>
</div></div></div>

<div class="modal fade" id="detailModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Detail Wali dan Anak</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="detail"></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Tutup</button></div></div></div></div>

<div class="modal fade" id="childModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content">
    <div class="modal-header"><div><h5 class="modal-title mb-0">Hubungkan Anak</h5><small id="childWaliName" class="text-muted"></small></div><button class="btn-close" data-bs-dismiss="modal"></button></div>
    <div class="modal-body"><input type="hidden" id="childWaliId"><div class="input-group mb-3"><input id="childSearch" class="form-control" placeholder="Cari NIS/NIM atau nama siswa"><button id="searchChild" class="btn btn-outline-primary" type="button"><i class="ri-search-line me-1"></i>Cari</button></div><div id="childResults" class="sdk-record-list"><div class="sdk-record-empty">Masukkan NIS/NIM atau nama siswa.</div></div><div class="form-check form-switch mt-3"><input class="form-check-input" type="checkbox" id="childPrimary"><label class="form-check-label" for="childPrimary">Jadikan wali utama untuk siswa ini</label></div></div>
    <div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary" id="saveChild">Hubungkan Anak</button></div>
</div></div></div>

<div class="modal fade" id="trashModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><div><h5 class="modal-title mb-0">Trash Wali Siswa</h5><small class="text-muted">Akun, data, dan relasi tidak dihapus permanen.</small></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div id="trashRows" class="sdk-record-list"><div class="sdk-record-empty">Memuat data...</div></div></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Tutup</button></div></div></div></div>

<script>
$(function(){
    const base=<?=json_encode(base_url('admin/dompet/wali_siswa/'),JSON_UNESCAPED_SLASHES)?>,csrf=<?=json_encode($csrf_token)?>;
    const formModal=new bootstrap.Modal(document.getElementById('formModal')),detailModal=new bootstrap.Modal(document.getElementById('detailModal')),childModal=new bootstrap.Modal(document.getElementById('childModal')),trashModal=new bootstrap.Modal(document.getElementById('trashModal'));
    let page=1,limit=10;
    const escapeHtml=value=>$('<div>').text(value==null||value===''?'-':value).html(),request=(url,data)=>$.post(base+url,data,null,'json'),fail=xhr=>Swal.fire({icon:'error',title:'Gagal',text:(xhr.responseJSON||{}).message||'Terjadi kesalahan.'});
    SDKreatifUI.refreshTooltips();
    function load(rebuildPager){request('result',{search:$('#search').val(),status:$('#waliStatusFilter').val(),page:page,limit:limit}).done(response=>{let html='';(response.data||[]).forEach((row,index)=>{html+=`<div class="sdk-record-card"><div class="sdk-record-head"><span>Hubungan: <strong>${escapeHtml(row.hubungan)}</strong></span>${SDKreatifUI.statusBadge(row.status_aktif)}</div><div class="sdk-record-main"><div class="flex-grow-1"><h5 class="sdk-record-title">${(page-1)*limit+index+1}. ${escapeHtml(row.nama_wali)}</h5><div class="sdk-record-meta"><span>Telepon: <strong>${escapeHtml(row.no_telp)}</strong></span><span>Jumlah Anak: <strong>${row.jumlah_anak}</strong></span><span>Akun: <strong>${escapeHtml(row.username)}</strong></span><span>Password: <strong>${escapeHtml(row.password_text)}</strong></span></div></div><div class="sdk-record-actions"><button class="btn btn-sm btn-outline-info detail" data-id="${row.id}" title="Detail" aria-label="Detail"><i class="ri-eye-line"></i></button><button class="btn btn-sm btn-outline-primary edit" data-id="${row.id}" title="Edit" aria-label="Edit"><i class="ri-edit-line"></i></button><button class="btn btn-sm btn-outline-success relate" data-id="${row.id}" data-name="${escapeHtml(row.nama_wali)}" title="Tambah anak" aria-label="Tambah anak"><i class="ri-user-add-line"></i></button><button class="btn btn-sm btn-outline-secondary toggle" data-id="${row.id}" data-status="${row.status_aktif==='AKTIF'?'NONAKTIF':'AKTIF'}" title="Ubah status" aria-label="Ubah status"><i class="ri-toggle-line"></i></button><button class="btn btn-sm btn-outline-warning pass" data-id="${row.id}" title="Reset password" aria-label="Reset password"><i class="ri-lock-password-line"></i></button><button class="btn btn-sm btn-outline-danger trash" data-id="${row.id}" title="Pindahkan ke Trash" aria-label="Pindahkan ke Trash"><i class="ri-delete-bin-6-line"></i></button></div></div></div>`;});$('#rows').html(html||'<div class="sdk-record-empty">Tidak ada data.</div>');page=response.meta.page;$('#info').text(response.meta.total+' wali');if(rebuildPager!==false)SDKreatifUI.serverPager('#waliPagination',response.meta,paging=>{page=paging.currentPage;load(false);});}).fail(fail);}
    function renderDetail(data){let children='';(data.anak||[]).forEach((child,index)=>{children+=`<div class="sdk-record-card"><div class="sdk-record-head"><span>NIS: <strong>${escapeHtml(child.nis)}</strong></span>${SDKreatifUI.statusBadge(child.status_siswa)}</div><div class="sdk-record-main"><div class="flex-grow-1"><h6 class="sdk-record-title">${index+1}. ${escapeHtml(child.nama_lengkap)}</h6><div class="sdk-record-meta"><span>Status relasi: ${SDKreatifUI.statusBadge(child.status_aktif)}</span><span>Wali utama: <strong>${child.status_utama==='YA'?'Ya':'Tidak'}</strong></span></div></div></div></div>`;});$('#detail').html(`<div class="border rounded p-3 mb-3"><div class="d-flex align-items-start justify-content-between gap-3"><div class="flex-grow-1"><h5 class="mb-1">${escapeHtml(data.nama_wali)}</h5><div class="text-muted">${escapeHtml(data.hubungan)} · ${escapeHtml(data.no_telp)} · ${escapeHtml(data.email)}</div></div><div class="flex-shrink-0 align-self-start">${SDKreatifUI.statusBadge(data.status_aktif)}</div></div>${data.alamat?`<div class="mt-2">${escapeHtml(data.alamat)}</div>`:''}</div><h6 class="mb-2">Anak Terhubung</h6><div class="sdk-record-list">${children||'<div class="sdk-record-empty">Belum ada anak yang dihubungkan.</div>'}</div>`);}
    function searchStudents(){const query=$('#childSearch').val().trim();$('#childResults').html('<div class="sdk-record-empty">Mencari siswa...</div>');request('cari_siswa',{search:query}).done(response=>{let html='';(response.data||[]).forEach(student=>{html+=`<label class="sdk-record-card student-choice" style="cursor:pointer"><div class="sdk-record-main"><div class="form-check mb-0"><input class="form-check-input child-student" type="radio" name="childStudent" value="${student.id}"></div><div class="flex-grow-1"><h6 class="sdk-record-title mb-1">${escapeHtml(student.nama_lengkap)}</h6><div class="sdk-record-meta"><span>NIS/NIM: <strong>${escapeHtml(student.nis)}</strong></span></div></div></div></label>`;});$('#childResults').html(html||'<div class="sdk-record-empty">Siswa aktif tidak ditemukan.</div>');}).fail(fail);}
    $('#add').on('click',()=>{$('#form')[0].reset();$('#form [name="id"]').val('');formModal.show();});
    $('#filter').on('click',()=>{page=1;load(true);});$('#search').on('keydown',event=>{if(event.key==='Enter'){page=1;load(true);}});$('#waliPageSize').on('change',function(){limit=parseInt(this.value,10)||10;page=1;load(true);});
    $('#save').on('click',()=>{
        const form=document.getElementById('form');
        if(!form.checkValidity()){
            form.reportValidity();
            return;
        }
        request('simpan',$('#form').serialize()).done(response=>{
            formModal.hide();
            const generated=response.data&&response.data.generated_password;
            if(generated){
                Swal.fire({
                    icon:'success',
                    title:'Wali dan akun berhasil dibuat',
                    html:`<div class="text-start"><p class="mb-3">Simpan kredensial berikut. Password hanya ditampilkan pada proses ini.</p><div class="border rounded p-3"><div><small class="text-muted">Username</small><div class="fw-bold">${escapeHtml(response.data.username)}</div></div><hr><div><small class="text-muted">Password</small><div class="fw-bold">${escapeHtml(generated)}</div></div></div></div>`,
                    confirmButtonText:'Sudah disimpan'
                });
            }else{
                Swal.fire('Berhasil',response.message,'success');
            }
            load(true);
        }).fail(fail);
    });
    $('#rows').on('click','.detail,.edit',function(){const edit=$(this).hasClass('edit');request('detail',{id:$(this).data('id')}).done(response=>{if(edit){Object.keys(response.data).forEach(key=>$('#form [name="'+key+'"]').val(response.data[key]));formModal.show();}else{renderDetail(response.data);detailModal.show();}}).fail(fail);});
    $('#rows').on('click','.relate',function(){$('#childWaliId').val($(this).data('id'));$('#childWaliName').text($(this).data('name'));$('#childSearch').val('');$('#childPrimary').prop('checked',false);$('#childResults').html('<div class="sdk-record-empty">Masukkan NIS/NIM atau nama siswa.</div>');childModal.show();setTimeout(()=>$('#childSearch').trigger('focus'),300);});
    $('#searchChild').on('click',searchStudents);$('#childSearch').on('keydown',event=>{if(event.key==='Enter'){event.preventDefault();searchStudents();}});$('#childResults').on('change','.child-student',function(){$('#childResults .student-choice').removeClass('border-primary');$(this).closest('.student-choice').addClass('border-primary');});
    $('#saveChild').on('click',function(){const button=this,student=$('#childResults .child-student:checked').val();if(!student)return Swal.fire('Pilih siswa','Pilih satu siswa yang akan dihubungkan.','warning');button.disabled=true;request('relasi',{id_wali:$('#childWaliId').val(),id_siswa:student,status_utama:$('#childPrimary').is(':checked')?'YA':'TIDAK',web_csrf_token:csrf}).done(response=>{childModal.hide();Swal.fire('Berhasil',response.message,'success');load(true);}).fail(fail).always(()=>button.disabled=false);});
    $('#rows').on('click','.toggle',function(){const id=$(this).data('id'),status=$(this).data('status'),active=status==='AKTIF';Swal.fire({title:active?'Aktifkan wali?':'Nonaktifkan wali?',text:active?'Akun wali dapat digunakan kembali.':'Akun login wali akan diblokir tanpa menghapus data dan relasi.',icon:'question',showCancelButton:true,confirmButtonText:active?'Aktifkan':'Nonaktifkan'}).then(result=>{if(result.isConfirmed)request('status',{id:id,status:status,web_csrf_token:csrf}).done(response=>{Swal.fire('Berhasil',response.message,'success');load(true);}).fail(fail);});});
    $('#rows').on('click','.pass',function(){const id=$(this).data('id');Swal.fire({title:'Password baru',input:'password',inputAttributes:{minlength:6},inputValidator:value=>(!value||value.length<6)?'Password minimal 6 karakter.':null,showCancelButton:true}).then(result=>{if(result.isConfirmed)request('reset_password',{id:id,password:result.value,web_csrf_token:csrf}).done(response=>Swal.fire('Berhasil',response.message,'success')).fail(fail);});});
    $('#rows').on('click','.trash',function(){const id=$(this).data('id');Swal.fire({title:'Pindahkan wali ke Trash?',text:'Akun login dinonaktifkan, tetapi data dan relasi anak tetap tersimpan.',icon:'warning',showCancelButton:true,confirmButtonText:'Pindahkan'}).then(result=>{if(result.isConfirmed)request('hapus',{id:id,web_csrf_token:csrf}).done(response=>{Swal.fire('Berhasil',response.message,'success');load(true);}).fail(fail);});});
    function loadTrash(){request('trash',{}).done(response=>{let html='';(response.data||[]).forEach((row,index)=>{html+=`<div class="sdk-record-card"><div class="sdk-record-head"><span>${escapeHtml(row.hubungan)}</span><span class="badge bg-danger">Trash</span></div><div class="sdk-record-main"><div class="flex-grow-1"><h6 class="sdk-record-title">${index+1}. ${escapeHtml(row.nama_wali)}</h6><div class="sdk-record-meta"><span>Telepon: <strong>${escapeHtml(row.no_telp)}</strong></span><span>Dihapus: <strong>${escapeHtml(row.tanggal)} ${escapeHtml(row.waktu)}</strong></span></div></div><div class="sdk-record-actions"><button class="btn btn-sm btn-outline-success restore-wali" data-id="${row.id}" title="Pulihkan" aria-label="Pulihkan"><i class="ri-arrow-go-back-line"></i></button></div></div></div>`;});$('#trashRows').html(html||'<div class="sdk-record-empty">Trash wali kosong.</div>');}).fail(fail);}
    $('#openTrash').on('click',()=>{loadTrash();trashModal.show();});
    $('#trashRows').on('click','.restore-wali',function(){request('restore',{id:$(this).data('id'),web_csrf_token:csrf}).done(response=>{Swal.fire('Berhasil',response.message,'success');loadTrash();load(true);}).fail(fail);});
    load(true);
});
</script>
